added = {}
for i, lang in enumerate(LANGS):
    path = os.path.join(ROOT, f'{lang}.ts')
    src = open(path, encoding='utf-8').read()
    lines = []
    for key, vals in T.items():
        v = vals[i]
        qkey = key.replace('\\', '\\\\').replace("'", "\\'")
        qval = v.replace('\\', '\\\\').replace("'", "\\'")
        # skip if the key already exists (quoted or bare identifier form)
        if f"'{qkey}':" in src or re.search(rf"^\s+{re.escape(key)}: ", src, re.M):
            continue
        lines.append(f"  '{qkey}': '{qval}',")
    if lines:
        block = "\n  /* ---------- Panel, materials & catalog names (v1.0.53) ---------- */\n" + "\n".join(lines) + "\n};"
        # replace the final closing brace
        idx = src.rstrip().rfind('};')
        src = src[:idx] + block + src.rstrip()[idx+2:] + '\n'
        open(path, 'w', encoding='utf-8').write(src)
    added[lang] = len(lines)
print('added per locale:', added)
